// HasAcceptedByWith applies the HasEdge predicate on the "accepted_by" edge with a given conditions (other predicates).
func HasAcceptedByWith(preds ...predicate.User) predicate.BlockVersion {
	return predicate.BlockVersion(func(s *sql.Selector) {
		step := newAcceptedByStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

