// And groups predicates with the AND operator between them.
func And(predicates ...predicate.BlockVersion) predicate.BlockVersion {
	return predicate.BlockVersion(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.BlockVersion) predicate.BlockVersion {
	return predicate.BlockVersion(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.BlockVersion) predicate.BlockVersion {
	return predicate.BlockVersion(sql.NotPredicates(p))
}
